function isEarthLeapYear(year){return year%4===0&&(year%100!==0||year%400===0)}
function earthDaysInYear(year){return isEarthLeapYear(year)?366:365}
function azaraEarthSecondsPerDay(year){return earthDaysInYear(year)*86400/AZARA_YEAR_DAYS}
function azaraEarthSecondsPerHour(year){return azaraEarthSecondsPerDay(year)/AZARA_DAY_HOURS}
function azaraEarthSecondsPerMinute(year){return azaraEarthSecondsPerHour(year)/60}
function positiveMod(n,m){return((n%m)+m)%m}
function azaraPartsFromDayFloat(dayFloat,earthYear=(new Date()).getUTCFullYear()){
  const yday=positiveMod(dayFloat,AZARA_YEAR_DAYS);
  const dayIndex=Math.floor(yday);
  const dayFraction=yday-dayIndex;
  const hourFloat=dayFraction*AZARA_DAY_HOURS;
  const hourIndex=Math.floor(hourFloat)+1;
  const minuteFloat=(hourFloat-Math.floor(hourFloat))*60;
  const minute=Math.floor(minuteFloat);
  const second=Math.floor((minuteFloat-minute)*60);
  const period=hourIndex<=7?"Ae":hourIndex<=14?"W’i":"La";
  const periodHour=((hourIndex-1)%7)+1;
  const notation=periodHour+period;
  const monthIndex=Math.floor(dayIndex/AZARA_MONTH_DAYS);
  const dayOfMonth=(dayIndex%AZARA_MONTH_DAYS)+1;
  const weekday=AZARA_WEEKDAYS[dayIndex%AZARA_WEEK_DAYS];
  const weekOfMonth=Math.floor((dayOfMonth-1)/AZARA_WEEK_DAYS)+1;
  const weekOfYear=Math.floor(dayIndex/AZARA_WEEK_DAYS)+1;
  return {earthYear,yday,dayIndex,dayNumber:dayIndex+1,dayFraction,hourFloat,hourIndex,minute,second,period,periodHour,notation,monthIndex,month:AZARA_MONTHS[monthIndex],dayOfMonth,weekday,weekOfMonth,weekOfYear};
}
function earthYearFrame(date=new Date()){
  const year=date.getFullYear();
  const start=new Date(year,0,1,0,0,0,0);
  const end=new Date(year+1,0,1,0,0,0,0);
  const spanMs=end.getTime()-start.getTime();
  return {year,startMs:start.getTime(),endMs:end.getTime(),spanMs,days:Math.round(spanMs/86400000)};
}
function azaraNow(date=new Date()){
  const frame=earthYearFrame(date);
  const progress=Math.max(0,Math.min(0.999999999,(date.getTime()-frame.startMs)/frame.spanMs));
  return azaraPartsFromDayFloat(progress*AZARA_YEAR_DAYS,frame.year);
}
function moonDominanceForHour(hour){
  if(hour===21)return "Arvalla + Duvaen";
  if(hour>=12&&hour<=14)return "W’iosamn + Arvalla";
  if(hour>=6&&hour<=7)return "Duvaen + W’iosamn";
  if(hour<=7)return "Duvaen";
  if(hour<=14)return "W’iosamn";
  return "Arvalla";
}
