  const visibleDuration=positiveMod(cfg.set-cfg.rise,AZARA_DAY_HOURS)||AZARA_DAY_HOURS;
  if(sinceRise<=visibleDuration){
    return -Math.PI/2+Math.PI*(sinceRise/visibleDuration);
  }
  const hiddenDuration=AZARA_DAY_HOURS-visibleDuration;
  return Math.PI/2+Math.PI*((sinceRise-visibleDuration)/hiddenDuration);
