  const nodeTheta=moonPathTheta(cfg.nodeHour,cfg);
  const direction=cfg.direction||1;
  const hTheta=(theta-nodeTheta)*direction;
  const oval=cfg.oval||1;
  let along=Math.sin(hTheta)*cfg.major*oval;
  let cross=Math.sin(hTheta*2)*cfg.minor;
  const bottomWeight=Math.pow(Math.max(0,-Math.cos(theta)),4);
