function drawMoonOrbitPaths(basis){
  const aza=planets.find(o=>o.data.name==="Aza'ra");if(!aza)return;
  ctx.save();
  Object.entries(MOON_PATH_CONFIG).forEach(([name,cfg])=>{
    ctx.strokeStyle=cfg.color;ctx.lineWidth=1.25;ctx.setLineDash([5,4]);ctx.beginPath();let first=true;
    for(let s=0;s<=168;s++){
      const h=AZARA_DAY_HOURS*s/168;
      const rel=moonPathPoint(name,h);
      const p=project({x:aza.pos.x+rel.x,y:aza.pos.y+rel.y,z:aza.pos.z+rel.z},basis);
      if(!p)continue;
      if(first){ctx.moveTo(p.x,p.y);first=false}else ctx.lineTo(p.x,p.y);
    }
    ctx.stroke();
    const rel=moonPathPoint(name,cfg.nodeHour);
    const node=project({x:aza.pos.x+rel.x,y:aza.pos.y+rel.y,z:aza.pos.z+rel.z},basis);
    if(node){ctx.setLineDash([]);ctx.fillStyle=cfg.color;ctx.beginPath();ctx.arc(node.x,node.y,2.4,0,TAU);ctx.fill();}
  });
  ctx.restore();
}

